const LITSAN_MARKER = "<!-- memmy:start v=1 -->";
/** Renders render litsan default skill manifest. */
export function renderLitsanDefaultSkillManifest(targetId) {
    return {
        targetId,
        content: renderLitsanDefaultContent(targetId),
        marker: LITSAN_MARKER
    };
}
export function renderLitsanDefaultContent(source) {
    return [
        "# LITSAN Memory CLI Skill",
        "",
        "Use `litsan-memory` to read and write the shared LITSAN memory substrate.",
        "",
        "## Ground Rules",
        "",
        "- Prefer the configured CLI: `litsan-memory ...`. If the local service is not preconfigured, pass `--url`, `--token`, or `--config`.",
        "- The CLI prints JSON. Parse fields such as `sessionId`, `turnId`, `injectedContext`, `hits`, and memory `id` from JSON instead of relying on display formatting.",
        `- All agents share one memory database. Always pass \`--source ${source}\` on Memory CLI commands from this agent.`,
        "- Use useful comma-separated `--tags` when writing durable memories.",
        "- Do not store secrets, tokens, private keys, raw credentials, or bulky logs. Store concise, self-contained facts, decisions, preferences, reusable procedures, and unresolved follow-ups.",
        "- Treat `<litsan_memory_context>` as historical memory only and `<current_user_request>` as the authoritative current task.",
        "- Never store `<litsan_memory_context>` or `<current_user_request>` tags with `litsan-memory add`; store only the durable fact itself.",
        "- If the memory service is unavailable, continue the task without inventing memory.",
        "",
        "## Health",
        "",
        "```bash",
        "litsan-memory health",
        "```",
        "",
        "## Agent Loop",
        "",
        "Open or resume a session before a task:",
        "",
        "```bash",
        `litsan-memory session open --source ${source} --workspace-path "$PWD"`,
        `litsan-memory session open --source ${source} --session-id "$SESSION_ID" --workspace-path "$PWD"`,
        "```",
        "",
        "At the start of a user turn, retrieve relevant context:",
        "",
        "```bash",
        `litsan-memory turn start --source ${source} --session-id "$SESSION_ID" --query "$USER_QUERY"`,
        "```",
        "",
        "Use returned `injectedContext` as historical memory context only. Keep the returned `turnId` for completion; the final `episodeId` is returned by `turn complete`. Keep the current user query separate from recalled memory.",
        "",
        "At the end of the turn, write the final interaction:",
        "",
        "```bash",
        `litsan-memory turn complete "$TURN_ID" --source ${source} --session-id "$SESSION_ID" --query "$USER_QUERY" --answer "$FINAL_ANSWER" --status succeeded`,
        "```",
        "",
        "Use `--status failed` for an actual failure. Do not call `turn complete` when the user cancels the turn. Close the session when the agent session is done:",
        "",
        "```bash",
        `litsan-memory session close "$SESSION_ID" --source ${source}`,
        "```",
        "",
        "## Search And Read",
        "",
        "Search when the user asks about prior context, preferences, project decisions, recurring bugs, known workflows, or anything that may already be in memory:",
        "",
        "```bash",
        `litsan-memory search "query text" --source ${source}`,
        `litsan-memory search "query text" --source ${source} --session-id "$SESSION_ID"`,
        "```",
        "",
        "Read details by id only; no `kind` is needed:",
        "",
        "```bash",
        `litsan-memory get "$MEMORY_ID" --source ${source}`,
        "```",
        "",
        "## Add Memory",
        "",
        "Add memory when you learn something durable or reusable:",
        "",
        "```bash",
        `litsan-memory add "The user prefers concise Chinese status updates." --title "User preference: status style" --tags user-preference --source ${source} --session-id "$SESSION_ID" --turn-id "$TURN_ID"`,
        "```",
        "",
        "## Delete Memory",
        "",
        "Delete only when the user asks or the memory is clearly invalid. Deletion only needs the memory id:",
        "",
        "```bash",
        `litsan-memory delete "$MEMORY_ID" --source ${source}`,
        "```"
    ].join("\n");
}
